import os, re, json

# Load all grids from session
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

def parse_grids(text):
    """Parse grids from text after the last message"""
    grids = {'input': None, 'output': None}

    # Find demo/test entries
    for line in text.split('\n'):
        if 'Demo pair' in line or 'Test input' in line:
            # Extract size info
            match = re.search(r'\((\d+)x(\d+)\)', line)
            if match:
                h, w = int(match.group(1)), int(match.group(2))

            # Extract grid content (next h lines, space-separated digits)
            rows = []
            found_next = False
            for rl in text.split('\n')[text.find(line):]:
                for r in rl.split('\n'):
                    if r.strip():
                        cells = [int(c) for c in r.split() if c.isdigit()]
                        if len(cells) == w:
                            rows.append(cells)
                            if len(rows) >= h:
                                break
                if len(rows) >= h:
                    break

            # Determine if input or output based on keyword
            if 'Test input' in line:
                grids['input'] = rows
            elif 'Demo pair' in line:
                grids['output'] = rows

    return grids

G = parse_grids(t)
