def classify_variants(components, h, w):
    """Try different reference points."""
    ref_points = ['first', 'last', 'top_left', 'bottom_right']  # removed center due to error
    results = {}

    for ref in ref_points:
        variants = []
        for comp_cells in components:
            if ref == 'first':
                r, c = comp_cells[0]
            elif ref == 'last':
                r, c = comp_cells[-1]
            elif ref == 'top_left':
                r, c = min(comp_cells, key=lambda x: (x[0], x[1]))
            elif ref == 'bottom_right':
                r, c = max(comp_cells, key=lambda x: (x[0], x[1]))

            out_r = int(r * 3 / h)
            out_c = int(c * 6 / w)
            variants.append((out_r, out_c))
        results[ref] = variants

    return results

